module wire_untangle (\n    input clk,\n    input rst_n,\n    input start,\n    input char_in,\n    input valid_in,\n    input last,\n    output reg done,\n    output reg result\n);\n\n    // Internal registers\n    reg [15:0] stack_data;  // Stack storage (16 bits)\n    reg [4:0] stack_depth;  // 5 bits (0-16)\n    reg finished;           // Completion flag\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            stack_data <= 16'b0;\n            stack_depth <= 5'b0;\n            done <= 1'b0;\n            result <= 1'b0;\n            finished <= 1'b0;\n        end else begin\n            if (start) begin\n                // Reset state on start pulse\n                stack_data <= 16'b0;\n                stack_depth <= 5'b0;\n                done <= 1'b0;\n                result <= 1'b0;\n                finished <= 1'b0;\n            end else if (valid_in && !finished) begin\n                if (stack_depth != 0 && stack_data[0] == char_in) begin\n                    // Pop matching character\n                    stack_data <= {1'b0, stack_data[15:1]};\n                    stack_depth <= stack_depth - 5'd1;\n                end else begin\n                    // Push new character\n                    if (stack_depth < 5'd16) begin\n                        stack_data <= {stack_data[14:0], char_in};\n                        stack_depth <= stack_depth + 5'd1;\n                    end\n                end\n                \n                if (last) begin\n                    done <= 1'b1;\n                    result <= (stack_depth == 5'b0) ? 1'b1 : 1'b0;\n                    finished <= 1'b1;\n                end else begin\n                    done <= 1'b0;\n                end\n            end else begin\n                done <= 1'b0;\n            end\n        end\n    end\n\nendmodule